"""Review authored turn isolated and connected to the new directional carry cycles."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
p=json.loads((HERE/'manifest.json').read_text());tracks=[]
states={s['id']:s for s in p['states']}
def add(track,folder,state):
 for file,d in zip(state['frameFiles'],state['frameDurationsMs']):
  track['files'].append((folder/file).relative_to(HERE.parent).as_posix());track['durations'].append(d);track['phases'].append(state['id'])
one={'label':'West ↔ north · master-matched rear pivot','files':[],'durations':[],'phases':[]}
for key in ['carry-turn-west-north','carry-turn-north-west']:add(one,HERE,states[key]);one['durations'][-1]+=500
tracks.append(one)
chain={'label':'Pickup → pivot → set-down · bare Bill','files':[],'durations':[],'phases':[],'turnOffset':12}
for direction,turn in [('west','carry-turn-west-north'),('north','carry-turn-north-west')]:
 folder=HERE.parent/f'bill-cargo-{direction}-coherent-v1';pack=json.loads((folder/'manifest.json').read_text());pickup=next(s for s in pack['states'] if s['id']=='pickup-'+direction)
 add(chain,folder,pickup)
 add(chain,HERE,states[turn])
 other='north' if direction=='west' else 'west';folder=HERE.parent/f'bill-cargo-{other}-coherent-v1';pack=json.loads((folder/'manifest.json').read_text());unload=next(s for s in pack['states'] if s['id']=='unload-'+other);add(chain,folder,unload);chain['durations'][-1]+=500
tracks.append(chain)
html='''<!doctype html><meta charset="utf-8"><title>Bill cargo carry turns</title><style>body{background:#152027;color:#e6eff1;font:16px system-ui;margin:20px}p{max-width:85ch;color:#bdd0d2}button,select,input{font:inherit;background:#29404a;color:white;padding:6px}.grid{display:flex;gap:12px;flex-wrap:wrap}.card{background:#22343e;padding:12px}canvas{display:block}label{margin-left:12px}</style><h1>Bill — west/north carry turns</h1><p>Three authored intermediate poses connect exact new west and north carry endpoints. Fixed source scale and matte calibration. North-to-west reverses the same poses. Original 800ms quarter-turn duration retained. Bare candidate staged for review; equipped turns follow.</p><button id="play">Pause</button><button id="step">Next turn pose</button><label>Height <select id="size"><option>148</option><option selected>82</option><option>54</option><option>27</option></select></label><label>Speed <select id="speed"><option value="1">1×</option><option value="0.5">0.5×</option></select></label><span id="status"> Loading…</span><div class="grid" id="grid"></div><script>
const tracks=TRACKS;let time=0,last=performance.now(),playing=true,manual=0;for(const t of tracks){let el=document.createElement('div');el.className='card';el.innerHTML='<strong>'+t.label+'</strong><canvas width="368" height="400"></canvas><small></small>';grid.append(el);t.card=el};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};document.querySelector('#step').onclick=()=>{playing=false;manual=(manual+1)%5;document.querySelector('#play').textContent='Play'};
Promise.all(tracks.map(async t=>{t.total=t.durations.reduce((a,b)=>a+b,0);t.images=await Promise.all(t.files.map(f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src='../'+f+'?v=turn-v1'})))})).then(()=>{document.querySelector('#status').textContent=' Both turn previews loaded';function draw(now){if(playing)time+=(now-last)*Number(document.querySelector('#speed').value);last=now;for(const t of tracks){let i=manual,v=time%t.total;if(playing){i=0;while(i<t.images.length-1&&v>=t.durations[i])v-=t.durations[i++]};const ctx=t.card.querySelector('canvas').getContext('2d'),s=Number(document.querySelector('#size').value)/148;ctx.clearRect(0,0,368,400);ctx.drawImage(t.images[i],184-128*s,350-224*s,256*s,256*s);t.card.querySelector('small').textContent=t.phases[i]+' · pose '+(i+1)}requestAnimationFrame(draw)}requestAnimationFrame(draw)}).catch(e=>document.querySelector('#status').textContent='Load failed '+e);</script>'''
html=html.replace('Three authored intermediate poses connect exact new west and north carry endpoints.','Revised intermediate anatomy matches the endpoint build using one frozen shoulder-width calibration. Four authored pivot poses connect exact neutral loaded endpoints. Feet remain under the body; the case turns with Bill.').replace('(manual+1)%5','(manual+1)%6').replace('let i=manual,v=time%t.total','let i=(t.turnOffset||0)+manual,v=time%t.total').replace('?v=turn-v1','?v=turn-v1')
html=html.replace('Revised intermediate anatomy matches the endpoint build using one frozen shoulder-width calibration.','Intermediate suit midtones now match both neutral loaded endpoints using one frozen material correction; shadows, outlines and matte highlights retained.').replace('?v=turn-v1','?v=grade-v2')
html=html.replace('Intermediate suit midtones now match both neutral loaded endpoints using one frozen material correction; shadows, outlines and matte highlights retained.','Planted west-to-north pivot with master ring insignia, swept hair, two-cylinder rear pack and three cyan vents. The case remains forward and becomes occluded as Bill faces north. Endpoint-derived matte grade keeps color continuity.').replace('?v=grade-v2','?v=turn-v1').replace('<div class="grid" id="grid">','<div class="grid" id="grid">')
(HERE/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)),encoding='utf-8')
print('Built isolated turn and connected cargo cycle browser reviews')
